import React from 'react';
import { motion } from 'framer-motion';
import { format } from 'date-fns';
import { FiCheck, FiCheckCircle, FiImage, FiFile, FiDownload } from 'react-icons/fi';

const MessageBubble = ({ message, isOwn, showAvatar }) => {
  const getMessageStatus = () => {
    if (message.isRead) return 'read';
    if (message.isDelivered) return 'delivered';
    return 'sent';
  };

  const formatTime = (timestamp) => {
    if (!timestamp) {
      return 'Just now';
    }
    
    try {
      const date = new Date(timestamp);
      if (isNaN(date.getTime())) {
        return 'Just now';
      }
      return format(date, 'HH:mm');
    } catch (error) {
      console.error('Error formatting timestamp:', error, 'timestamp:', timestamp);
      return 'Just now';
    }
  };

  const renderMessageContent = () => {
    // Debug: log the message object to see what we're getting
    console.log('MessageBubble - message object:', message);
    
    // Default to text if messageType is not set or invalid
    const messageType = message.messageType || 'text';
    
    if (messageType === 'text') {
      return (
        <p className="text-sm whitespace-pre-wrap break-words">
          {message.content}
        </p>
      );
    }

    if (message.messageType === 'image') {
      return (
        <div className="space-y-2">
          <img
            src={message.attachments?.[0]?.fileUrl}
            alt="Shared image"
            className="max-w-xs rounded-lg cursor-pointer hover:opacity-90 transition-opacity"
            onClick={() => window.open(message.attachments[0].fileUrl, '_blank')}
          />
          {message.content && (
            <p className="text-sm whitespace-pre-wrap break-words">
              {message.content}
            </p>
          )}
        </div>
      );
    }

    if (message.messageType === 'document' || message.messageType === 'file') {
      const attachment = message.attachments?.[0];
      return (
        <div className="space-y-2">
          <div className="flex items-center space-x-3 p-3 bg-gray-100 rounded-lg max-w-xs">
            <div className="p-2 bg-white rounded-lg">
              <FiFile className="w-5 h-5 text-gray-600" />
            </div>
            <div className="flex-1 min-w-0">
              <p className="text-sm font-medium text-gray-900 truncate">
                {attachment?.originalName || 'File'}
              </p>
              <p className="text-xs text-gray-500">
                {attachment?.fileSize ? `${(attachment.fileSize / 1024).toFixed(1)} KB` : 'Unknown size'}
              </p>
            </div>
            <button
              onClick={() => window.open(attachment?.fileUrl, '_blank')}
              className="p-1 text-gray-500 hover:text-gray-700 transition-colors"
            >
              <FiDownload className="w-4 h-4" />
            </button>
          </div>
          {message.content && (
            <p className="text-sm whitespace-pre-wrap break-words">
              {message.content}
            </p>
          )}
        </div>
      );
    }

    return (
      <p className="text-sm text-gray-500 italic">
        Unsupported message type
      </p>
    );
  };

  const renderMessageStatus = () => {
    const status = getMessageStatus();
    
    if (isOwn) {
      return (
        <div className="flex items-center space-x-1 mt-1">
          <span className="text-xs text-gray-500">
            {formatTime(message.createdAt)}
          </span>
          <div className="flex items-center">
            {status === 'sent' && <FiCheck className="w-3 h-3 text-gray-400" />}
            {status === 'delivered' && <FiCheck className="w-3 h-3 text-gray-400" />}
            {status === 'read' && <FiCheckCircle className="w-3 h-3 text-blue-500" />}
          </div>
        </div>
      );
    }

    return (
      <span className="text-xs text-gray-500 mt-1">
        {formatTime(message.createdAt)}
      </span>
    );
  };

  return (
    <div className={`flex ${isOwn ? 'justify-end' : 'justify-start'} ${showAvatar ? 'mt-4' : 'mt-1'}`}>
      <div className={`flex items-end space-x-2 max-w-xs lg:max-w-md ${isOwn ? 'flex-row-reverse space-x-reverse' : ''}`}>
        {/* Avatar */}
        {!isOwn && showAvatar && (
          <div className="w-8 h-8 bg-gradient-to-r from-primary-500 to-health-500 rounded-full flex items-center justify-center flex-shrink-0">
            <span className="text-white font-medium text-xs">
              {message.sender?.fullName?.charAt(0)?.toUpperCase() || 'U'}
            </span>
          </div>
        )}

        {/* Message Bubble */}
        <motion.div
          initial={{ opacity: 0, scale: 0.8 }}
          animate={{ opacity: 1, scale: 1 }}
          transition={{ duration: 0.2 }}
          className={`relative px-4 py-2 rounded-2xl ${
            isOwn
              ? 'bg-primary-600 text-white rounded-br-sm'
              : 'bg-gray-100 text-gray-900 rounded-bl-sm'
          }`}
        >
          {/* Message Content */}
          {renderMessageContent()}

          {/* Edited Indicator */}
          {message.isEdited && (
            <span className="text-xs opacity-70 italic">(edited)</span>
          )}

          {/* Message Status and Time */}
          <div className={`flex items-center ${isOwn ? 'justify-end' : 'justify-start'}`}>
            {renderMessageStatus()}
          </div>
        </motion.div>

        {/* Own Avatar */}
        {isOwn && showAvatar && (
          <div className="w-8 h-8 bg-gradient-to-r from-gray-500 to-gray-600 rounded-full flex items-center justify-center flex-shrink-0">
            <span className="text-white font-medium text-xs">
              {message.sender?.fullName?.charAt(0)?.toUpperCase() || 'U'}
            </span>
          </div>
        )}
      </div>
    </div>
  );
};

export default MessageBubble;
